import{_ as t,o as s,c as r,a3 as o}from"./chunks/framework.Ch_0qWu9.js";const m=JSON.parse('{"title":"Resource inventories","description":"","frontmatter":{"sourcePath":"assets/README.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/29e5ae6c70cf7268cd38de5cf59f4e08507b1ff6/assets/README.md","alternateUrl":"/TCSExam/docs/zh/resources/assets/","alternateAnchors":{"resource-inventories":"resource-inventories"}},"headers":[],"relativePath":"resources/assets/index.md","filePath":"resources/assets/index.md"}'),a={name:"resources/assets/index.md"};function i(d,e,n,c,u,p){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="resource-inventories" tabindex="-1">Resource inventories <a class="header-anchor" href="#resource-inventories" aria-label="Permalink to &quot;Resource inventories&quot;">​</a></h1><p>These manifests describe task environments, data preparation and source provenance. They are for contributors maintaining the build recipes; paths are repository-relative.</p><table tabindex="0"><thead><tr><th>File or directory</th><th>Contents</th></tr></thead><tbody><tr><td><code>images.json</code></td><td>Runtime, tool and data products, image identities, dependencies and acquisition recipes</td></tr><tr><td><code>files.json</code></td><td>Omitted source inputs, paths, sizes, hashes, modes and distribution conditions</td></tr><tr><td><code>sources.json</code></td><td>Source commits, original hashes and current packaging hashes</td></tr><tr><td><code>data/</code></td><td>Data preparation recipes, per-file manifests and the common data-image Dockerfile</td></tr><tr><td><code>build-inputs.json</code></td><td>Dockerfile FROM/COPY/ADD dependencies and omitted inputs</td></tr><tr><td><code>resource-groups.json</code></td><td>Omitted files grouped by purpose and distribution conditions</td></tr><tr><td><code>environments/lean-base/</code></td><td>Shared Lean build materials and dependency pins</td></tr><tr><td><code>environments/cpsolver/</code></td><td>CPSolver source and build materials; see <a href="/TCSExam/docs/licenses/cpsolver-source/">instructions</a></td></tr></tbody></table><p>Use <code>tcsexam build</code> to prepare a selection from these recipes. It downloads fixed inputs, builds dependencies and assembles the complete images used by Harbor. Data images supply files at build time. The resulting image identities are stored in the local cache for <code>doctor</code> and <code>run</code>. An external <code>artifacts.json</code> provides optional immutable image assignments. See <a href="/TCSExam/docs/resources/">resource preparation</a> for the commands and input requirements.</p><p>Keep public practice data, hidden judging data and reference answers in their respective products. Development and public self-test images must exclude hidden inputs from every layer. A complete image inherits its inputs&#39; <a href="/TCSExam/docs/licenses/distribution/">distribution conditions</a>.</p><p>Store generated images, datasets, jobs and private configuration outside the source package. <a href="/TCSExam/docs/contributing/">Contributing</a> describes source checks and export.</p>',6)])])}const h=t(a,[["render",i]]);export{m as __pageData,h as default};
